select distinct count(a.record_id) from chemical_file a join data_file_status b ON b.file_id = a.file_id


		and b.platform=#{platform}



		and b.analysis_date= #{analysis_date} 


		and b.subbarcode =#{subbarcode}


		and b.product_name =#{product_name}


	and ( '1' is null

			or (a.report =1 or a.report is null or report='')


			or (a.report =0 and report!='')


			or a.mapped_allele_id is null


			or a.mapped_allele_id is not null

		)



			and (a.report =1 or a.report is null or report='')


			and (a.report =0 and report!='')


			and a.mapped_allele_id is null


			and a.mapped_allele_id is not null

SELECT distinct a.* FROM chemical_file a join data_file_status b ON b.file_id = a.file_id


		and b.platform=#{platform}



		and b.analysis_date= #{analysis_date} 


		and b.subbarcode =#{subbarcode}


		and b.product_name =#{product_name}



	and ( '1' is null

			or (a.report =1 or a.report is null or report='')


			or (a.report =0 and report!='')


			or a.mapped_allele_id is null


			or a.mapped_allele_id is not null

		)



			and (a.report =1 or a.report is null or report='')


			and (a.report =0 and report!='')


			and a.mapped_allele_id is null


			and a.mapped_allele_id is not null




limit #{pageNo},#{pageSize}

